import numpy as np
import scipy.linalg
from solver import Solver

solver = Solver()

# Simulate the is_solution check
def is_solution(problem, solution):
    A = problem.get('matrix')
    if A is None:
        return False

    n = A.shape[0]
    if A.shape != (n, n):
        return False

    if not isinstance(solution, dict) or 'sqrtm' not in solution:
        return False
    sqrtm_dict = solution['sqrtm']
    if not isinstance(sqrtm_dict, dict) or 'X' not in sqrtm_dict:
        return False

    proposed_X_list = sqrtm_dict['X']

    if not isinstance(proposed_X_list, list):
        return False

    try:
        proposed_X = np.array(proposed_X_list, dtype=complex)
    except ValueError:
        return False

    if proposed_X.shape != (n, n):
        return False

    if not np.all(np.isfinite(proposed_X)):
        return False

    try:
        A_reconstructed = proposed_X @ proposed_X
    except Exception:
        return False

    rtol = 1e-5
    atol = 1e-8
    is_close = np.allclose(A_reconstructed, A, rtol=rtol, atol=atol)

    return is_close

# Test with various inputs
np.random.seed(42)
all_pass = True
for n in [1, 2, 3, 4, 8, 16, 32, 64]:
    for trial in range(10):
        A = np.random.randn(n, n) + 1j * np.random.randn(n, n)
        problem = {'matrix': A}

        solution = solver.solve(problem)

        if not is_solution(problem, solution):
            print(f'FAIL: n={n} trial={trial}')
            all_pass = False

if all_pass:
    print('All is_solution checks passed!')
